 47→  voiceMode: "off" | "next" | "on" = "off";
 48→  dangerousMode: boolean = false;
 49→  archiving: boolean = false;
 50→  log: Logger;
 51→
 52→  readonly permissionGate = new PermissionGate();
 53→  private readonly queue: PromptQueue;
 54→  private speechService?: SpeechService;
 55→
 56→  constructor(opts: {
 57→    id?: string;
 58→    channelId: string;
 59→    agentName: string;
 60→    workingDirectory: string;
 61→    agentInstance: AgentInstance;
 62→    speechService?: SpeechService;
 63→  }) {
 64→    super();
 65→    this.id = opts.id || nanoid(12);
 66→    this.channelId = opts.channelId;
 67→    this.agentName = opts.agentName;
 68→    this.workingDirectory = opts.workingDirectory;
 69→    this.agentInstance = opts.agentInstance;
 70→    this.speechService = opts.speechService;
 71→    this.log = createSessionLogger(this.id, moduleLog);
 72→    this.log.info({ agentName: this.agentName }, "Session created");
 73→
 74→    this.queue = new PromptQueue(
 75→      (text, attachments) => this.processPrompt(text, attachments),
 76→      (err) => {
 77→        this.fail("Prompt execution failed");
 78→        this.log.error({ err }, "Prompt execution failed");
 79→      },
 80→    );
 81→  }
 82→
 83→  // --- State Machine ---
 84→
 85→  get status(): SessionStatus {
 86→    return this._status;
 87→  }
 88→
 89→
 90→  /** Transition to active — from initializing, error, or cancelled */
 91→  activate(): void {
 92→    this.transition("active");
 93→  }
 94→
 95→  /** Transition to error — from initializing or active */
 96→  fail(reason: string): void {
 97→    this.transition("error");
 98→    this.emit("error", new Error(reason));
 99→  }
100→
101→  /** Transition to finished — from active only. Emits session_end for backward compat. */
102→  finish(reason?: string): void {
103→    this.transition("finished");
104→    this.emit("session_end", reason ?? "completed");
105→  }
106→
107→  /** Transition to cancelled — from active only (terminal session cancel) */
108→  markCancelled(): void {
109→    this.transition("cancelled");
110→  }
111→
112→  private transition(to: SessionStatus): void {
113→    const from = this._status;
114→    const allowed = VALID_TRANSITIONS[from];
115→    if (!allowed?.has(to)) {
116→      throw new Error(
117→        `Invalid session transition: ${from} → ${to}`,
118→      );
119→    }
120→    this._status = to;
121→    this.log.debug({ from, to }, "Session status transition");
122→    this.emit("status_change", from, to);
123→  }
124→
125→  /** Number of prompts waiting in queue */
126→  get queueDepth(): number {
127→    return this.queue.pending;
128→  }
129→
130→  get promptRunning(): boolean {
131→    return this.queue.isProcessing;
132→  }
133→
134→  // --- Voice Mode ---
135→
136→  setVoiceMode(mode: "off" | "next" | "on"): void {
137→    this.voiceMode = mode;
138→    this.log.info({ voiceMode: mode }, "TTS mode changed");
139→  }
140→
141→  // --- Public API ---
142→
143→  async enqueuePrompt(text: string, attachments?: Attachment[]): Promise<void> {
144→    await this.queue.enqueue(text, attachments);
145→  }
146→
147→  private async processPrompt(text: string, attachments?: Attachment[]): Promise<void> {
148→    if (text === "\x00__warmup__") {
149→      await this.runWarmup();
150→      return;
151→    }
152→
153→    if (this._status === "initializing") {
154→      this.activate();
155→    }
156→    const promptStart = Date.now();
157→    this.log.debug("Prompt execution started");
158→
159→    // STT: transcribe audio attachments if agent doesn't support audio
160→    const processed = await this.maybeTranscribeAudio(text, attachments);
161→
162→    // TTS: determine if TTS is active for this prompt
163→    const ttsActive =
164→      this.voiceMode !== "off" &&
165→      !!this.speechService?.isTTSAvailable();
166→
167→    // TTS: inject prompt instruction
168→    if (ttsActive) {
169→      processed.text += TTS_PROMPT_INSTRUCTION;
170→      if (this.voiceMode === "next") {
171→        this.voiceMode = "off";
172→      }
173→    }
174→
175→    // TTS: set up text accumulator before prompting
176→    let accumulatedText = "";
177→    const accumulatorListener = ttsActive
178→      ? (event: AgentEvent) => {
179→          if (event.type === "text") {
180→            accumulatedText += event.content;
181→          }
182→        }
183→      : null;
184→
185→    if (accumulatorListener) {
186→      this.on("agent_event", accumulatorListener);
187→    }
188→
189→    try {
190→      await this.agentInstance.prompt(processed.text, processed.attachments);
191→    } finally {
192→      if (accumulatorListener) {
193→        this.off("agent_event", accumulatorListener);
194→      }
195→    }
196→
197→    this.log.info(
198→      { durationMs: Date.now() - promptStart },
199→      "Prompt execution completed",
200→    );
201→
202→    // TTS: fire-and-forget post-response synthesis
203→    if (ttsActive && accumulatedText) {
204→      this.processTTSResponse(accumulatedText).catch((err) => {
205→        this.log.warn({ err }, "TTS post-processing failed");
206→      });
207→    }
208→
209→    if (!this.name) {
210→      await this.autoName();
211→    }
212→  }
213→
214→  private async maybeTranscribeAudio(
215→    text: string,
216→    attachments?: Attachment[],
217→  ): Promise<{ text: string; attachments?: Attachment[] }> {
218→    if (!attachments?.length || !this.speechService) {
219→      return { text, attachments };
220→    }
221→
222→    const hasAudioCapability = this.agentInstance.promptCapabilities?.audio === true;
223→    if (hasAudioCapability) {
224→      return { text, attachments };
225→    }
226→
227→    if (!this.speechService.isSTTAvailable()) {
228→      return { text, attachments };
229→    }
230→
231→    let transcribedText = text;
232→    const remainingAttachments: Attachment[] = [];
233→
234→    for (const att of attachments) {
235→      if (att.type !== "audio") {
236→        remainingAttachments.push(att);
237→        continue;
238→      }
239→
240→      try {
241→        const audioPath = att.originalFilePath || att.filePath;
242→        const audioMime = att.originalFilePath ? "audio/ogg" : att.mimeType;
243→        const audioBuffer = await fs.promises.readFile(audioPath);
244→        const result = await this.speechService.transcribe(audioBuffer, audioMime);
245→        this.log.info({ provider: "stt", duration: result.duration }, "Voice transcribed");
246→        // Notify user of transcription result
247→        this.emit("agent_event", {
248→          type: "system_message",
249→          message: `🎤 You said: ${result.text}`,
250→        });
251→        // Strip [Audio: ...] placeholder since we have the transcription
252→        transcribedText = transcribedText.replace(/\[Audio:\s*[^\]]*\]\s*/g, "").trim();
253→        transcribedText = transcribedText
254→          ? `${transcribedText}\n${result.text}`
255→          : result.text;
256→      } catch (err) {
257→        this.log.warn({ err }, "STT transcription failed, keeping audio attachment");
258→        this.emit("agent_event", {
259→          type: "error",
260→          message: `Voice transcription failed: ${(err as Error).message}`,
261→        });
262→        remainingAttachments.push(att);
263→      }
264→    }
265→
266→    return {
267→      text: transcribedText,
268→      attachments: remainingAttachments.length > 0 ? remainingAttachments : undefined,
269→    };
270→  }
271→
272→  private async processTTSResponse(responseText: string): Promise<void> {
273→    const match = TTS_BLOCK_REGEX.exec(responseText);
274→    if (!match?.[1]) {
275→      this.log.debug("No [TTS] block found in response, skipping synthesis");
276→      return;
277→    }
278→
279→    let ttsText = match[1].trim();
280→    if (!ttsText) return;
281→
282→    if (ttsText.length > TTS_MAX_LENGTH) {
283→      ttsText = ttsText.slice(0, TTS_MAX_LENGTH);
284→    }
285→
286→    try {
287→      const timeoutPromise = new Promise<never>((_, reject) =>
288→        setTimeout(() => reject(new Error("TTS synthesis timed out")), TTS_TIMEOUT_MS),
289→      );
290→      const result = await Promise.race([
291→        this.speechService!.synthesize(ttsText),
292→        timeoutPromise,
293→      ]);
294→      const base64 = result.audioBuffer.toString("base64");
295→      this.emit("agent_event", {
296→        type: "audio_content",
297→        data: base64,
298→        mimeType: result.mimeType,
299→      });
300→      this.log.info("TTS synthesis completed");
301→    } catch (err) {
302→      this.log.warn({ err }, "TTS synthesis failed, skipping");
303→    }
304→  }
305→
306→  // NOTE: This injects a summary prompt into the agent's conversation history.
307→  private async autoName(): Promise<void> {
308→    let title = "";
309→
310→    // Temporarily remove all agent_event listeners so auto-name output
311→    // is not forwarded to the adapter. Add a capture-only listener instead.
312→    const captureHandler = (event: AgentEvent) => {
313→      if (event.type === "text") title += event.content;
314→      // Swallow all other events from auto-name prompt
315→    };
316→
317→    // Pause the session emitter so agent_event emissions from SessionBridge
318→    // don't reach the adapter during auto-name. The AgentInstance emitter
319→    // stays active — we just intercept with our capture handler.
320→    this.pause((event) => event !== "agent_event");
321→    this.agentInstance.on("agent_event", captureHandler);
322→
323→    try {
324→      await this.agentInstance.prompt(
325→        "Summarize this conversation in max 5 words for a topic title. Reply ONLY with the title, nothing else.",
326→      );
327→      this.name = title.trim().slice(0, 50) || `Session ${this.id.slice(0, 6)}`;
328→      this.log.info({ name: this.name }, "Session auto-named");
329→
330→      // Emit named event — SessionBridge listens to rename the thread
331→      this.emit("named", this.name);
332→    } catch {
333→      this.name = `Session ${this.id.slice(0, 6)}`;
334→    } finally {
335→      this.agentInstance.off("agent_event", captureHandler);
336→      // Discard buffered auto-name agent_events, then resume normal delivery
337→      this.clearBuffer();
338→      this.resume();
339→    }
340→  }
341→
342→  /** Fire-and-forget warm-up: primes model cache while user types their first message */
343→  async warmup(): Promise<void> {
344→    // Route through PromptQueue to prevent concurrent prompt execution.
345→    // Any user prompts arriving during warmup will be queued and drained after.
346→    await this.queue.enqueue("\x00__warmup__");
347→  }
348→
349→  private async runWarmup(): Promise<void> {
350→    // Pause events but let commands_update pass through
351→    this.pause((_event, args) => {
352→      const agentEvent = args[0] as AgentEvent;
353→      return agentEvent?.type === "commands_update";
354→    });
355→
356→    try {
357→      const start = Date.now();
358→      await this.agentInstance.prompt('Reply with only "ready".');
359→      this.activate();
360→      this.log.info({ durationMs: Date.now() - start }, "Warm-up complete");
361→    } catch (err) {
362→      this.log.error({ err }, "Warm-up failed");
363→    } finally {
364→      this.clearBuffer();
365→      this.resume();
366→    }
367→  }
368→
369→  /** Cancel the current prompt and clear the queue. Stays in active state. */
370→  async abortPrompt(): Promise<void> {
371→    this.queue.clear();
372→    this.log.info("Prompt aborted");
373→    await this.agentInstance.cancel();
374→  }
375→
376→  async destroy(): Promise<void> {
377→    this.log.info("Session destroyed");
378→    await this.agentInstance.destroy();
379→  }
380→}
