  8→export function buildDangerousModeKeyboard(sessionId: string, enabled: boolean): InlineKeyboard {
  9→  return new InlineKeyboard().text(
 10→    enabled ? "🔐 Disable Dangerous Mode" : "☠️ Enable Dangerous Mode",
