171→export async function handleTTS(ctx: Context, core: OpenACPCore): Promise<void> {
172→  const threadId = ctx.message?.message_thread_id;
173→  if (!threadId) {
174→    await ctx.reply("⚠️ This command only works inside a session topic.", { parse_mode: "HTML" });
175→    return;
176→  }
177→  const session = await core.getOrResumeSession("telegram", String(threadId));
178→  if (!session) {
179→    await ctx.reply("⚠️ No active session in this topic.", { parse_mode: "HTML" });
180→    return;
181→  }
182→
183→  const args = ctx.message?.text?.split(/\s+/).slice(1) ?? [];
184→  const arg = args[0]?.toLowerCase();
185→
186→  if (arg === "on") {
187→    session.setVoiceMode("on");
188→    await ctx.reply("🔊 Text to Speech enabled for this session.", { parse_mode: "HTML" });
189→  } else if (arg === "off") {
190→    session.setVoiceMode("off");
191→    await ctx.reply("🔇 Text to Speech disabled.", { parse_mode: "HTML" });
192→  } else {
193→    session.setVoiceMode("next");
194→    await ctx.reply("🔊 Text to Speech enabled for the next message.", { parse_mode: "HTML" });
195→  }
196→}
