198→export async function handleUpdate(ctx: Context, core: OpenACPCore): Promise<void> {
199→  if (!core.requestRestart) {
200→    await ctx.reply("⚠️ Update is not available (no restart handler registered).", { parse_mode: "HTML" });
201→    return;
202→  }
203→
204→  const { getCurrentVersion, getLatestVersion, compareVersions, runUpdate } = await import("../../../cli/version.js");
205→  const current = getCurrentVersion();
206→  const statusMsg = await ctx.reply(`🔍 Checking for updates... (current: v${escapeHtml(current)})`, { parse_mode: "HTML" });
207→
208→  const latest = await getLatestVersion();
209→  if (!latest) {
210→    await ctx.api.editMessageText(ctx.chat!.id, statusMsg.message_id, "❌ Could not check for updates.", { parse_mode: "HTML" });
211→    return;
212→  }
213→
214→  if (compareVersions(current, latest) >= 0) {
215→    await ctx.api.editMessageText(ctx.chat!.id, statusMsg.message_id, `✅ Already up to date (v${escapeHtml(current)}).`, { parse_mode: "HTML" });
216→    return;
217→  }
218→
219→  await ctx.api.editMessageText(
220→    ctx.chat!.id,
221→    statusMsg.message_id,
222→    `⬇️ Updating v${escapeHtml(current)} → v${escapeHtml(latest)}...`,
223→    { parse_mode: "HTML" },
224→  );
225→
226→  const ok = await runUpdate();
227→  if (!ok) {
228→    await ctx.api.editMessageText(ctx.chat!.id, statusMsg.message_id, "❌ Update failed. Try manually: <code>npm install -g @openacp/cli@latest</code>", { parse_mode: "HTML" });
229→    return;
230→  }
231→
232→  await ctx.api.editMessageText(
233→    ctx.chat!.id,
234→    statusMsg.message_id,
235→    `✅ Updated to v${escapeHtml(latest)}. Restarting...`,
236→    { parse_mode: "HTML" },
237→  );
238→
239→  await new Promise((r) => setTimeout(r, 500));
240→  await core.requestRestart();
241→}
242→
243→export async function handleRestart(ctx: Context, core: OpenACPCore): Promise<void> {
244→  if (!core.requestRestart) {
245→    await ctx.reply("⚠️ Restart is not available (no restart handler registered).", { parse_mode: "HTML" });
246→    return;
247→  }
248→  await ctx.reply("🔄 <b>Restarting OpenACP...</b>\nRebuilding and restarting. Be back shortly.", { parse_mode: "HTML" });
249→  // Give Telegram a moment to deliver the message before shutting down
250→  await new Promise((r) => setTimeout(r, 500));
251→  await core.requestRestart();
252→}
