  9→ * Creates them if their IDs are null, then persists the IDs via saveConfig.
 10→ *
 11→ * saveConfig uses nested object path: { channels: { discord: { forumChannelId: ... } } }
 12→ */
 13→export async function ensureForums(
 14→  guild: Guild,
 15→  config: {
 16→    forumChannelId: string | null
 17→    notificationChannelId: string | null
 18→  },
 19→  saveConfig: (updates: Record<string, unknown>) => Promise<void>,
 20→): Promise<{ forumChannel: ForumChannel | TextChannel; notificationChannel: TextChannel }> {
 21→  let forumChannelId = config.forumChannelId
 22→  let notificationChannelId = config.notificationChannelId
 23→
 24→  // Ensure forum/sessions channel exists — fetch existing or create new
 25→  let forumChannel: ForumChannel | TextChannel | null = null
 26→  if (forumChannelId) {
 27→    try {
 28→      const ch = guild.channels.cache.get(forumChannelId)
 29→        ?? await guild.channels.fetch(forumChannelId)
 30→      if (ch && (ch.type === ChannelType.GuildForum || ch.type === ChannelType.GuildText)) {
 31→        forumChannel = ch as ForumChannel | TextChannel
 32→        log.info({ forumChannelId, type: ch.type }, '[forums] Reusing existing sessions channel')
 33→      }
 34→    } catch {
 35→      log.warn({ forumChannelId }, '[forums] Saved sessions channel not found, recreating...')
 36→    }
 37→  }
 38→  if (!forumChannel) {
 39→    // Prefer Forum Channel (requires Community mode), fallback to Text Channel with threads
 40→    if (guild.features.includes('COMMUNITY')) {
 41→      const channel = await guild.channels.create({
 42→        name: 'openacp-sessions',
 43→        type: ChannelType.GuildForum,
 44→      })
 45→      forumChannel = channel as ForumChannel
 46→      log.info({ forumChannelId: channel.id }, '[forums] Created forum channel')
 47→    } else {
 48→      const channel = await guild.channels.create({
 49→        name: 'openacp-sessions',
 50→        type: ChannelType.GuildText,
 51→      })
 52→      forumChannel = channel as TextChannel
 53→      log.info({ forumChannelId: channel.id }, '[forums] Created text channel (Community mode not enabled, using threads fallback)')
 54→    }
 55→    await saveConfig({ channels: { discord: { forumChannelId: forumChannel.id } } })
 56→  }
 57→
 58→  // Ensure notification channel exists — fetch existing or create new
 59→  let notificationChannel: TextChannel | null = null
 60→  if (notificationChannelId) {
 61→    try {
 62→      const ch = guild.channels.cache.get(notificationChannelId)
 63→        ?? await guild.channels.fetch(notificationChannelId)
 64→      if (ch && ch.type === ChannelType.GuildText) {
 65→        notificationChannel = ch as TextChannel
 66→        log.info({ notificationChannelId }, '[forums] Reusing existing notification channel')
 67→      }
 68→    } catch {
 69→      log.warn({ notificationChannelId }, '[forums] Saved notification channel not found, recreating...')
 70→    }
 71→  }
 72→  if (!notificationChannel) {
 73→    const channel = await guild.channels.create({
 74→      name: 'openacp-notifications',
 75→      type: ChannelType.GuildText,
 76→    })
 77→    notificationChannel = channel as TextChannel
 78→    await saveConfig({ channels: { discord: { notificationChannelId: channel.id } } })
 79→    log.info({ notificationChannelId: channel.id }, '[forums] Created notification channel')
 80→  }
 81→
 82→  return { forumChannel, notificationChannel }
 83→}
 84→
 85→// ─── createSessionThread ──────────────────────────────────────────────────────
 86→
 87→/**
 88→ * Creates a new thread for a session.
 89→ * - Forum Channel: creates a forum post (thread with initial message)
 90→ * - Text Channel: creates a public thread
 91→ */
 92→export async function createSessionThread(
 93→  forumChannel: ForumChannel | TextChannel,
 94→  name: string,
 95→): Promise<ThreadChannel> {
 96→  if (forumChannel.type === ChannelType.GuildForum) {
 97→    // Forum channel: create a post (thread with initial message)
 98→    const thread = await (forumChannel as ForumChannel).threads.create({
 99→      name,
100→      message: { content: '⏳ Setting up...' },
101→    })
102→    return thread
103→  }
104→
105→  // Text channel fallback: send a message first, then create a thread on it
106→  const textChannel = forumChannel as TextChannel
107→  const msg = await textChannel.send({ content: `📂 **${name}** — ⏳ Setting up...` })
108→  const thread = await msg.startThread({ name })
109→  return thread
110→}
111→
112→// ─── renameSessionThread ──────────────────────────────────────────────────────
113→
114→/**
115→ * Fetches and renames a thread. Ignores all errors (thread may be deleted/archived).
116→ */
117→export async function renameSessionThread(
118→  guild: Guild,
119→  threadId: string,
120→  newName: string,
121→): Promise<void> {
122→  try {
123→    const channel = guild.channels.cache.get(threadId)
124→      ?? await guild.channels.fetch(threadId)
125→    if (channel && 'setName' in channel) {
126→      await (channel as ThreadChannel).setName(newName)
127→    }
128→  } catch {
129→    // Ignore — thread may be deleted or archived
130→  }
131→}
132→
133→// ─── deleteSessionThread ──────────────────────────────────────────────────────
134→
135→/**
136→ * Archives and locks a thread instead of permanently deleting it.
137→ * Unlike Telegram (which just closes a topic), Discord delete is permanent
138→ * and destroys all messages. Archiving preserves the conversation history.
139→ */
140→export async function deleteSessionThread(
141→  guild: Guild,
142→  threadId: string,
143→): Promise<void> {
144→  try {
145→    const channel = guild.channels.cache.get(threadId)
146→      ?? await guild.channels.fetch(threadId)
147→    if (channel && channel.isThread()) {
148→      const thread = channel as ThreadChannel
149→      if (!thread.archived) {
150→        await thread.setArchived(true)
151→      }
152→      if (!thread.locked) {
153→        await thread.setLocked(true)
154→      }
155→    }
156→  } catch {
157→    // Ignore — thread may already be deleted or inaccessible
158→  }
159→}
160→
161→// ─── ensureUnarchived ─────────────────────────────────────────────────────────
162→
163→/**
164→ * If the thread is archived, unarchives it.
165→ */
166→export async function ensureUnarchived(thread: ThreadChannel): Promise<void> {
167→  if (thread.archived) {
168→    try {
169→      await thread.setArchived(false)
170→    } catch (err) {
171→      log.warn({ err, threadId: thread.id }, '[forums] Failed to unarchive thread')
172→    }
173→  }
174→}
175→
176→// ─── buildDeepLink ────────────────────────────────────────────────────────────
177→
178→/**
179→ * Builds a Discord deep link URL to a channel/thread, optionally to a specific message.
180→ */
181→export function buildDeepLink(
182→  guildId: string,
183→  channelId: string,
184→  messageId?: string,
185→): string {
186→  const base = `https://discord.com/channels/${guildId}/${channelId}`
187→  return messageId ? `${base}/${messageId}` : base
188→}
