 49→    const config = configManager.get();
 50→    this.agentCatalog = new AgentCatalog();
 51→    this.agentCatalog.load();
 52→    this.agentManager = new AgentManager(this.agentCatalog);
 53→    const storePath = path.join(os.homedir(), ".openacp", "sessions.json");
 54→    this.sessionStore = new JsonFileSessionStore(
 55→      storePath,
 56→      config.sessionStore.ttlDays,
 57→    );
 58→    this.sessionManager = new SessionManager(this.sessionStore);
 59→    this.securityGuard = new SecurityGuard(configManager, this.sessionManager);
 60→    this.notificationManager = new NotificationManager(this.adapters);
 61→
 62→    // Usage tracking
 63→    const usageConfig = config.usage;
 64→    if (usageConfig.enabled) {
 65→      const usagePath = path.join(os.homedir(), ".openacp", "usage.json");
 66→      this.usageStore = new UsageStore(usagePath, usageConfig.retentionDays);
 67→      this.usageBudget = new UsageBudget(this.usageStore, usageConfig);
 68→    }
