 70→    this.messageTransformer = new MessageTransformer();
 71→    this.eventBus = new EventBus();
 72→    this.sessionManager.setEventBus(this.eventBus);
 73→    this.fileService = new FileService(
 74→      path.join(os.homedir(), ".openacp", "files"),
 75→    );
 76→
 77→    // Initialize speech service
 78→    const speechConfig = config.speech ?? {
 79→      stt: { provider: null, providers: {} },
 80→      tts: { provider: null, providers: {} },
 81→    };
 82→    this.speechService = new SpeechService(speechConfig);
 83→
 84→    // Register built-in STT providers
 85→    const groqConfig = speechConfig.stt?.providers?.groq;
 86→    if (groqConfig?.apiKey) {
 87→      this.speechService.registerSTTProvider(
