107→    // Hot-reload: handle config changes that need side effects
108→    this.configManager.on(
109→      "config:changed",
110→      async ({ path: configPath, value }: { path: string; value: unknown }) => {
111→        if (configPath === "logging.level" && typeof value === "string") {
112→          const { setLogLevel } = await import("./log.js");
113→          setLogLevel(value);
114→          log.info({ level: value }, "Log level changed at runtime");
115→        }
116→        if (configPath.startsWith("speech.")) {
117→          const newConfig = this.configManager.get();
118→          const newSpeechConfig = newConfig.speech ?? {
119→            stt: { provider: null, providers: {} },
120→            tts: { provider: null, providers: {} },
121→          };
122→          this.speechService.updateConfig(newSpeechConfig);
123→          const groqCfg = newSpeechConfig.stt?.providers?.groq;
124→          if (groqCfg?.apiKey) {
125→            this.speechService.registerSTTProvider(
126→              "groq",
127→              new GroqSTT(groqCfg.apiKey, groqCfg.model),
128→            );
129→          }
130→          // Re-register TTS providers on config change
131→          const ttsCfg = newSpeechConfig.tts;
132→          if (ttsCfg?.provider === "edge-tts") {
133→            const edgeConfig = ttsCfg.providers?.["edge-tts"];
134→            const voice = edgeConfig?.voice as string | undefined;
135→            this.speechService.registerTTSProvider("edge-tts", new EdgeTTS(voice));
136→          }
137→          log.info("Speech service config updated at runtime");
138→        }
139→      },
140→    );
