  1→import type { TextChannel, ThreadChannel, Message } from 'discord.js'
  2→import { splitMessage } from './formatting.js'
  3→import type { DiscordSendQueue } from './send-queue.js'
  4→
  5→const FLUSH_INTERVAL = 5000
  6→const MAX_DISPLAY_LENGTH = 1900
  7→
  8→export class MessageDraft {
  9→  private buffer: string = ''
 10→  private message?: Message
 11→  private flushTimer?: ReturnType<typeof setTimeout>
 12→  private flushPromise: Promise<void> = Promise.resolve()
 13→  private lastSentBuffer: string = ''
 14→  private displayTruncated = false
 15→  private firstFlushPending = false
 16→
 17→  constructor(
 18→    private thread: TextChannel | ThreadChannel,
 19→    private sendQueue: DiscordSendQueue,
 20→    private sessionId: string,
 21→  ) {}
 22→
 23→  append(text: string): void {
 24→    if (!text) return
 25→    this.buffer += text
 26→    this.scheduleFlush()
 27→  }
 28→
 29→  getBuffer(): string {
 30→    return this.buffer
 31→  }
 32→
 33→  private scheduleFlush(): void {
 34→    if (this.flushTimer) return
 35→    this.flushTimer = setTimeout(() => {
 36→      this.flushTimer = undefined
 37→      this.flushPromise = this.flushPromise
 38→        .then(() => this.flush())
 39→        .catch(() => {})
 40→    }, FLUSH_INTERVAL)
 41→  }
 42→
 43→  async flush(): Promise<void> {
 44→    if (!this.buffer) return
 45→    if (this.firstFlushPending) return
 46→
 47→    // Snapshot buffer before any await — append() can be called concurrently
 48→    const snapshot = this.buffer
 49→
 50→    let content = snapshot
 51→    let truncated = false
 52→    if (content.length > MAX_DISPLAY_LENGTH) {
 53→      content = snapshot.slice(0, MAX_DISPLAY_LENGTH) + '…'
 54→      truncated = true
 55→    }
 56→
 57→    if (!content) return
 58→
 59→    if (!this.message) {
 60→      this.firstFlushPending = true
 61→      try {
 62→        const result = await this.sendQueue.enqueue(
 63→          () => this.thread.send({ content }),
 64→          { type: 'other' },
 65→        )
 66→        if (result) {
 67→          this.message = result
 68→          if (!truncated) {
 69→            this.lastSentBuffer = snapshot
 70→            this.displayTruncated = false
 71→          } else {
 72→            this.displayTruncated = true
 73→          }
 74→        }
 75→      } catch {
 76→        // send failed — next flush will retry
 77→      } finally {
 78→        this.firstFlushPending = false
 79→      }
 80→    } else {
 81→      // Skip if content hasn't changed since last send
 82→      if (!truncated && snapshot === this.lastSentBuffer) return
 83→
 84→      try {
 85→        const result = await this.sendQueue.enqueue(
 86→          () => this.message!.edit({ content }),
 87→          { type: 'text', key: this.sessionId },
 88→        )
 89→        // Only mark as sent if the edit was actually executed (not deduped/dropped)
 90→        if (result !== undefined) {
 91→          if (!truncated) {
 92→            this.lastSentBuffer = snapshot
 93→            this.displayTruncated = false
 94→          } else {
 95→            this.displayTruncated = true
 96→          }
 97→        }
 98→      } catch {
 99→        // Don't reset message — transient errors should not cause duplicate sends
100→      }
101→    }
102→  }
103→
104→  async finalize(): Promise<void> {
105→    if (this.flushTimer) {
106→      clearTimeout(this.flushTimer)
107→      this.flushTimer = undefined
108→    }
109→
110→    // Wait for any in-progress flush to complete
111→    await this.flushPromise
112→
113→    if (!this.buffer) return
114→
115→    // Skip if buffer was already fully sent and nothing new appended
116→    if (this.message && this.buffer === this.lastSentBuffer && !this.displayTruncated) {
117→      return
118→    }
119→
120→    // Try to send full buffer as a single message (most common case)
121→    if (this.buffer.length <= MAX_DISPLAY_LENGTH) {
122→      const content = this.buffer
123→      try {
124→        if (this.message) {
125→          await this.sendQueue.enqueue(
126→            () => this.message!.edit({ content }),
127→            { type: 'other' },
128→          )
129→        } else {
130→          await this.sendQueue.enqueue(
131→            () => this.thread.send({ content }),
132→            { type: 'other' },
133→          )
134→        }
135→        return
136→      } catch {
137→        // Fall through to split approach
138→      }
139→    }
140→
141→    // Buffer exceeds limit or single send failed — split and send chunks
142→    const chunks = splitMessage(this.buffer, MAX_DISPLAY_LENGTH)
143→
144→    for (let i = 0; i < chunks.length; i++) {
145→      const content = chunks[i]
146→      try {
147→        if (i === 0 && this.message) {
148→          await this.sendQueue.enqueue(
149→            () => this.message!.edit({ content }),
150→            { type: 'other' },
151→          )
152→        } else {
153→          const msg = await this.sendQueue.enqueue(
154→            () => this.thread.send({ content }),
155→            { type: 'other' },
156→          )
157→          if (msg) {
158→            this.message = msg
159→          }
160→        }
161→      } catch {
162→        // Skip this chunk — best effort
163→      }
164→    }
165→  }
166→}
