  1→import type { Session } from "./session.js";
  2→import type { ChannelAdapter } from "./channel.js";
  3→import type { MessageTransformer } from "./message-transformer.js";
  4→import type { NotificationManager } from "./notification.js";
  5→import type { SessionManager } from "./session-manager.js";
  6→import type { AgentEvent, PermissionRequest, SessionStatus } from "./types.js";
  7→import type { EventBus } from "./event-bus.js";
  8→import { FileService } from "./file-service.js";
  9→import { createChildLogger } from "./log.js";
 10→
 11→const log = createChildLogger({ module: "session-bridge" });
 12→
 13→export interface BridgeDeps {
 14→  messageTransformer: MessageTransformer;
 15→  notificationManager: NotificationManager;
 16→  sessionManager: SessionManager;
 17→  eventBus?: EventBus;
 18→  fileService?: FileService;
 19→}
 20→
 21→export class SessionBridge {
 22→  private connected = false;
 23→  private agentEventHandler?: (event: AgentEvent) => void;
 24→  private sessionEventHandler?: (event: AgentEvent) => void;
 25→  private statusChangeHandler?: (
 26→    from: SessionStatus,
 27→    to: SessionStatus,
 28→  ) => void;
 29→  private namedHandler?: (name: string) => void;
 30→
 31→  constructor(
 32→    private session: Session,
 33→    private adapter: ChannelAdapter,
 34→    private deps: BridgeDeps,
 35→  ) {}
 36→
 37→  connect(): void {
 38→    if (this.connected) return;
 39→    this.connected = true;
 40→
 41→    this.wireAgentToSession();
 42→    this.wireSessionToAdapter();
 43→    this.wirePermissions();
 44→    this.wireLifecycle();
 45→  }
 46→
 47→  disconnect(): void {
 48→    if (!this.connected) return;
 49→    this.connected = false;
 50→
 51→    if (this.agentEventHandler) {
 52→      this.session.agentInstance.off("agent_event", this.agentEventHandler);
 53→    }
 54→    if (this.sessionEventHandler) {
 55→      this.session.off("agent_event", this.sessionEventHandler);
 56→    }
 57→    if (this.statusChangeHandler) {
 58→      this.session.off("status_change", this.statusChangeHandler);
 59→    }
 60→    if (this.namedHandler) {
 61→      this.session.off("named", this.namedHandler);
 62→    }
 63→
 64→    // Reset agent callbacks to no-op
 65→    this.session.agentInstance.onPermissionRequest = async () => "";
 66→  }
 67→
 68→  private wireAgentToSession(): void {
 69→    this.agentEventHandler = (event: AgentEvent) => {
 70→      this.session.emit("agent_event", event);
 71→    };
 72→    this.session.agentInstance.on("agent_event", this.agentEventHandler);
 73→  }
 74→
 75→  private wireSessionToAdapter(): void {
 76→    const session = this.session;
 77→    const ctx = {
 78→      get id() {
 79→        return session.id;
 80→      },
 81→      get workingDirectory() {
 82→        return session.workingDirectory;
 83→      },
 84→    };
 85→
 86→    this.sessionEventHandler = (event: AgentEvent) => {
 87→      switch (event.type) {
 88→        case "text":
 89→        case "thought":
 90→        case "tool_call":
 91→        case "tool_update":
 92→        case "plan":
 93→        case "usage":
 94→          this.adapter.sendMessage(
 95→            this.session.id,
 96→            this.deps.messageTransformer.transform(event, ctx),
 97→          );
 98→          break;
 99→
100→        case "session_end":
101→          this.session.finish(event.reason);
102→          this.adapter.cleanupSkillCommands(this.session.id);
103→          this.adapter.sendMessage(
104→            this.session.id,
105→            this.deps.messageTransformer.transform(event),
106→          );
107→          this.deps.notificationManager.notify(this.session.channelId, {
108→            sessionId: this.session.id,
109→            sessionName: this.session.name,
110→            type: "completed",
111→            summary: `Session "${this.session.name || this.session.id}" completed`,
112→          });
113→          break;
114→
115→        case "error":
116→          this.session.fail(event.message);
117→          this.adapter.cleanupSkillCommands(this.session.id);
118→          this.adapter.sendMessage(
119→            this.session.id,
120→            this.deps.messageTransformer.transform(event),
121→          );
122→          this.deps.notificationManager.notify(this.session.channelId, {
123→            sessionId: this.session.id,
124→            sessionName: this.session.name,
125→            type: "error",
126→            summary: event.message,
127→          });
128→          break;
129→
130→        case "image_content": {
131→          if (this.deps.fileService) {
132→            const fs = this.deps.fileService;
133→            const sid = this.session.id;
134→            const { data, mimeType } = event;
135→            const buffer = Buffer.from(data, "base64");
136→            const ext = FileService.extensionFromMime(mimeType);
137→            fs.saveFile(sid, `agent-image${ext}`, buffer, mimeType)
138→              .then((att) => {
139→                this.adapter.sendMessage(sid, {
140→                  type: "attachment",
141→                  text: "",
142→                  attachment: att,
143→                });
144→              })
145→              .catch((err) => log.error({ err }, "Failed to save agent image"));
146→          }
147→          break;
148→        }
149→        case "audio_content": {
150→          if (this.deps.fileService) {
151→            const fs = this.deps.fileService;
152→            const sid = this.session.id;
153→            const { data, mimeType } = event;
154→            const buffer = Buffer.from(data, "base64");
155→            const ext = FileService.extensionFromMime(mimeType);
156→            fs.saveFile(sid, `agent-audio${ext}`, buffer, mimeType)
157→              .then((att) => {
158→                this.adapter.sendMessage(sid, {
159→                  type: "attachment",
160→                  text: "",
161→                  attachment: att,
162→                });
163→              })
