191→  private wirePermissions(): void {
192→    this.session.agentInstance.onPermissionRequest = async (
193→      request: PermissionRequest,
194→    ) => {
195→      this.session.emit("permission_request", request);
196→      this.deps.eventBus?.emit("permission:request", {
197→        sessionId: this.session.id,
198→        permission: request,
199→      });
200→
201→      // Auto-approve openacp CLI commands
202→      if (request.description.toLowerCase().includes("openacp")) {
203→        const allowOption = request.options.find((o) => o.isAllow);
204→        if (allowOption) {
205→          log.info(
206→            { sessionId: this.session.id, requestId: request.id },
207→            "Auto-approving openacp command",
208→          );
209→          return allowOption.id;
210→        }
211→      }
212→
213→      // Dangerous mode: auto-approve all permissions
214→      if (this.session.dangerousMode) {
215→        const allowOption = request.options.find((o) => o.isAllow);
216→        if (allowOption) {
217→          log.info(
218→            { sessionId: this.session.id, requestId: request.id, optionId: allowOption.id },
219→            "Dangerous mode: auto-approving permission",
220→          );
221→          return allowOption.id;
222→        }
223→      }
224→
225→      // Set pending BEFORE sending UI to avoid race condition
226→      const promise = this.session.permissionGate.setPending(request);
227→
228→      // Send permission UI to session topic
229→      await this.adapter.sendPermissionRequest(this.session.id, request);
230→
231→      // Wait for user response — adapter resolves this promise
232→      return promise;
233→    };
234→  }
235→
236→  private wireLifecycle(): void {
237→    // Persist status changes and auto-disconnect on terminal states
238→    this.statusChangeHandler = (from: SessionStatus, to: SessionStatus) => {
239→      this.deps.sessionManager.patchRecord(this.session.id, {
240→        status: to,
241→        lastActiveAt: new Date().toISOString(),
242→      });
243→      this.deps.eventBus?.emit("session:updated", {
244→        sessionId: this.session.id,
245→        status: to,
246→      });
247→
248→      // Auto-disconnect on terminal states
249→      if (to === "finished" || to === "cancelled") {
250→        // Disconnect on next tick so current event handlers can complete
251→        queueMicrotask(() => this.disconnect());
252→      }
253→    };
254→    this.session.on("status_change", this.statusChangeHandler);
255→
256→    // Persist and relay name changes
257→    this.namedHandler = (name: string) => {
258→      this.deps.sessionManager.patchRecord(this.session.id, { name });
259→      this.deps.eventBus?.emit("session:updated", {
260→        sessionId: this.session.id,
261→        name,
262→      });
263→      this.adapter.renameSessionThread(this.session.id, name);
264→    };
265→    this.session.on("named", this.namedHandler);
266→  }
