 79→/**
 80→ * Wraps native fetch to work around grammY's polyfilled AbortController.
 81→ * grammY uses abort-controller polyfill whose AbortSignal fails instanceof
 82→ * checks in Node 24+ native fetch. This wrapper re-creates a native
 83→ * AbortSignal from the polyfilled one before passing it to fetch.
 84→ */
 85→function patchedFetch(
 86→  input: RequestInfo | URL,
 87→  init?: RequestInit,
 88→): Promise<Response> {
 89→  if (init?.signal && !(init.signal instanceof AbortSignal)) {
 90→    const nativeController = new AbortController();
 91→    const polyfillSignal = init.signal as unknown as {
 92→      aborted: boolean;
 93→      addEventListener: (event: string, fn: () => void) => void;
 94→    };
 95→    if (polyfillSignal.aborted) {
 96→      nativeController.abort();
 97→    } else {
 98→      polyfillSignal.addEventListener("abort", () => nativeController.abort());
 99→    }
100→    init = { ...init, signal: nativeController.signal };
101→  }
102→  return fetch(input, init);
103→}
