30→      throw new Error("STT not configured. Set speech.stt.provider and API key in config.");
31→    }
32→    const provider = this.sttProviders.get(providerName);
33→    if (!provider) {
34→      throw new Error(`STT provider "${providerName}" not registered. Available: ${[...this.sttProviders.keys()].join(", ") || "none"}`);
35→    }
36→    return provider.transcribe(audioBuffer, mimeType, options);
37→  }
