43→    }
44→    const provider = this.ttsProviders.get(providerName);
45→    if (!provider) {
46→      throw new Error(`TTS provider "${providerName}" not registered. Available: ${[...this.ttsProviders.keys()].join(", ") || "none"}`);
47→    }
48→    return provider.synthesize(text, options);
49→  }
