  1→import type { Message, TextChannel, ThreadChannel } from 'discord.js'
  2→import { log } from '../../core/log.js'
  3→import type { AgentCommand } from '../../core/types.js'
  4→import type { SessionManager } from '../../core/session-manager.js'
  5→import type { DiscordPlatformData } from '../../core/types.js'
  6→import type { DiscordSendQueue } from './send-queue.js'
  7→
  8→const DISCORD_MSG_LIMIT = 1900
  9→
 10→function buildSkillContent(commands: AgentCommand[]): string {
 11→  const sorted = [...commands].sort((a, b) => a.name.localeCompare(b.name))
 12→  const header = '**Available Skills**\n'
 13→  const lines = sorted.map((c) => `\`/${c.name}\``)
 14→  let content = header
 15→  for (const line of lines) {
 16→    const candidate = content + '\n' + line
 17→    if (candidate.length > DISCORD_MSG_LIMIT) break
 18→    content = candidate
 19→  }
 20→  return content
 21→}
 22→
 23→export class SkillCommandManager {
 24→  private messages: Map<string, Message> = new Map()
 25→
 26→  constructor(
 27→    private sendQueue: DiscordSendQueue,
 28→    private sessionManager: SessionManager,
 29→  ) {}
 30→
 31→  async send(
 32→    sessionId: string,
 33→    thread: TextChannel | ThreadChannel,
 34→    commands: AgentCommand[],
 35→  ): Promise<void> {
 36→    // Restore from persisted platform data if not in memory
 37→    if (!this.messages.has(sessionId)) {
 38→      const record = this.sessionManager.getSessionRecord(sessionId)
 39→      const platform = record?.platform as DiscordPlatformData | undefined
 40→      if (platform?.skillMsgId) {
 41→        try {
 42→          const msg = await thread.messages.fetch(platform.skillMsgId)
 43→          if (msg) this.messages.set(sessionId, msg)
 44→        } catch {
 45→          // Message may no longer exist — will send a new one
 46→        }
 47→      }
 48→    }
 49→
 50→    // Empty commands → remove pinned message
 51→    if (commands.length === 0) {
 52→      await this.cleanup(sessionId)
 53→      return
 54→    }
 55→
 56→    const content = buildSkillContent(commands)
 57→    const existingMsg = this.messages.get(sessionId)
 58→
 59→    if (existingMsg) {
 60→      try {
 61→        await existingMsg.edit({ content })
 62→        return
 63→      } catch (err: unknown) {
 64→        const msg = err instanceof Error ? err.message : ''
 65→        if (msg.includes('Unknown Message') || msg.includes('10008')) {
 66→          // Message no longer exists — fall through to send a new one
 67→          this.messages.delete(sessionId)
 68→        } else {
 69→          // Transient error or not-modified — just return
 70→          return
 71→        }
 72→      }
 73→    }
 74→
 75→    // Send new message and pin it
 76→    try {
 77→      const msg = await this.sendQueue.enqueue(
 78→        () => thread.send({ content }),
 79→        { type: 'other' },
 80→      )
 81→
 82→      if (!msg) return
 83→
 84→      this.messages.set(sessionId, msg)
 85→
 86→      // Persist skillMsgId so it survives restarts
 87→      const record = this.sessionManager.getSessionRecord(sessionId)
 88→      if (record) {
 89→        await this.sessionManager.patchRecord(sessionId, {
 90→          platform: { ...record.platform, skillMsgId: msg.id },
 91→        })
 92→      }
 93→
 94→      // Pin the message
 95→      try {
 96→        await msg.pin()
 97→      } catch (err) {
 98→        log.warn({ err, sessionId }, '[SkillCommandManager] Failed to pin skill message')
 99→      }
100→    } catch (err) {
101→      log.error({ err, sessionId }, '[SkillCommandManager] Failed to send skill commands')
102→    }
103→  }
104→
105→  async cleanup(sessionId: string): Promise<void> {
106→    const msg = this.messages.get(sessionId)
107→    this.messages.delete(sessionId)
108→
109→    if (msg) {
110→      try {
111→        await msg.edit({ content: '*Session ended*' })
112→        await msg.unpin()
113→      } catch {
114→        // Message may already be deleted
115→      }
116→    }
117→
118→    // Clear persisted skillMsgId
119→    const record = this.sessionManager.getSessionRecord(sessionId)
120→    if (record) {
121→      const platform = record.platform
122→      if (platform && typeof platform === 'object' && 'threadId' in platform) {
123→        const { skillMsgId: _removed, ...rest } = platform as unknown as DiscordPlatformData
124→        await this.sessionManager.patchRecord(sessionId, { platform: rest })
125→      }
126→    }
127→  }
128→}
