 4→
 5→export class EdgeTTS implements TTSProvider {
 6→  readonly name = "edge-tts";
 7→  private voice: string;
 8→
 9→  constructor(voice?: string) {
10→    this.voice = voice || DEFAULT_VOICE;
11→  }
12→
13→  async synthesize(text: string, options?: TTSOptions): Promise<TTSResult> {
14→    const { MsEdgeTTS, OUTPUT_FORMAT } = await import("msedge-tts");
15→    const tts = new MsEdgeTTS();
16→
17→    const voice = options?.voice || this.voice;
18→    const format = OUTPUT_FORMAT.AUDIO_24KHZ_48KBITRATE_MONO_MP3;
19→
20→    await tts.setMetadata(voice, format);
21→    const { audioStream } = tts.toStream(text);
22→
23→    const chunks: Buffer[] = [];
24→    for await (const chunk of audioStream) {
25→      chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
26→    }
27→
28→    tts.close();
29→
30→    return {
31→      audioBuffer: Buffer.concat(chunks),
32→      mimeType: "audio/mpeg",
33→    };
34→  }
35→}
