 4→import {
 5→  detectAction,
 6→  storeAction,
 7→  buildActionKeyboard,
 8→} from "./action-detect.js";
 9→
10→export class DraftManager {
11→  private drafts: Map<string, MessageDraft> = new Map();
12→  private textBuffers: Map<string, string> = new Map();
13→
14→  constructor(
15→    private bot: Bot,
16→    private chatId: number,
17→    private sendQueue: TelegramSendQueue,
18→  ) {}
19→
20→  getOrCreate(sessionId: string, threadId: number): MessageDraft {
21→    let draft = this.drafts.get(sessionId);
22→    if (!draft) {
23→      draft = new MessageDraft(
24→        this.bot,
25→        this.chatId,
26→        threadId,
27→        this.sendQueue,
28→        sessionId,
29→      );
30→      this.drafts.set(sessionId, draft);
31→    }
32→    return draft;
33→  }
34→
35→  hasDraft(sessionId: string): boolean {
36→    return this.drafts.has(sessionId);
37→  }
38→
39→  getDraft(sessionId: string): MessageDraft | undefined {
40→    return this.drafts.get(sessionId);
41→  }
42→
43→  appendText(sessionId: string, text: string): void {
44→    this.textBuffers.set(
45→      sessionId,
46→      (this.textBuffers.get(sessionId) ?? "") + text,
47→    );
48→  }
49→
50→  /**
51→   * Finalize the current draft and return the message ID.
52→   * Optionally detects actions in assistant responses.
53→   */
54→  async finalize(
55→    sessionId: string,
56→    assistantSessionId?: string,
57→  ): Promise<void> {
58→    const draft = this.drafts.get(sessionId);
59→    if (!draft) return;
60→
61→    // Delete BEFORE awaiting to prevent concurrent finalizeDraft() calls
62→    // from double-finalizing the same draft
63→    this.drafts.delete(sessionId);
64→    const finalMsgId = await draft.finalize();
65→
66→    // Detect actions in assistant responses and attach keyboard
67→    if (assistantSessionId && sessionId === assistantSessionId) {
68→      const fullText = this.textBuffers.get(sessionId);
69→      this.textBuffers.delete(sessionId);
70→      if (fullText && finalMsgId) {
71→        const detected = detectAction(fullText);
72→        if (detected) {
73→          const actionId = storeAction(detected);
74→          const keyboard = buildActionKeyboard(actionId, detected);
75→          try {
76→            await this.bot.api.editMessageReplyMarkup(
77→              this.chatId,
78→              finalMsgId,
79→              { reply_markup: keyboard },
80→            );
81→          } catch {
82→            // Best effort — keyboard attachment is non-critical
83→          }
84→        }
85→      }
86→    } else {
87→      this.textBuffers.delete(sessionId);
88→    }
89→  }
90→
91→  cleanup(sessionId: string): void {
92→    this.drafts.delete(sessionId);
93→    this.textBuffers.delete(sessionId);
94→  }
