  1→import type { Bot, Context } from "grammy";
  2→import { InlineKeyboard } from "grammy";
  3→import type { OpenACPCore } from "../../../core/index.js";
  4→import { getSafeFields, resolveOptions, getConfigValue, isHotReloadable, type ConfigFieldDef } from "../../../core/config-registry.js";
  5→import { createChildLogger } from "../../../core/log.js";
  6→
  7→const log = createChildLogger({ module: "telegram-settings" });
  8→
  9→function buildSettingsKeyboard(core: OpenACPCore): InlineKeyboard {
 10→  const config = core.configManager.get();
 11→  const fields = getSafeFields();
 12→  const kb = new InlineKeyboard();
 13→
 14→  for (const field of fields) {
 15→    const value = getConfigValue(config, field.path);
 16→    const label = formatFieldLabel(field, value);
 17→
 18→    if (field.type === 'toggle') {
 19→      kb.text(`${label}`, `s:toggle:${field.path}`).row();
 20→    } else if (field.type === 'select') {
 21→      kb.text(`${label}`, `s:select:${field.path}`).row();
 22→    } else {
 23→      kb.text(`${label}`, `s:input:${field.path}`).row();
 24→    }
 25→  }
 26→
 27→  kb.text("◀️ Back to Menu", "s:back");
 28→  return kb;
 29→}
 30→
 31→function formatFieldLabel(field: ConfigFieldDef, value: unknown): string {
 32→  const icons: Record<string, string> = {
 33→    agent: '🤖', logging: '📝', tunnel: '🔗',
 34→    security: '🔒', workspace: '📁', storage: '💾', speech: '🎤',
 35→  };
 36→  const icon = icons[field.group] ?? '⚙️';
 37→
 38→  if (field.type === 'toggle') {
 39→    return `${icon} ${field.displayName}: ${value ? 'ON' : 'OFF'}`;
 40→  }
 41→  const displayValue = value === null || value === undefined ? 'Not set' : String(value);
 42→  return `${icon} ${field.displayName}: ${displayValue}`;
 43→}
 44→
 45→export async function handleSettings(ctx: Context, core: OpenACPCore): Promise<void> {
 46→  const kb = buildSettingsKeyboard(core);
 47→  await ctx.reply(`<b>⚙️ Settings</b>\nTap to change:`, {
 48→    parse_mode: "HTML",
 49→    reply_markup: kb,
 50→  });
 51→}
 52→
 53→export function setupSettingsCallbacks(
 54→  bot: Bot,
 55→  core: OpenACPCore,
 56→  getAssistantSession: () => { topicId: number; enqueuePrompt: (p: string) => Promise<void> } | undefined,
 57→): void {
 58→  bot.callbackQuery(/^s:toggle:/, async (ctx) => {
 59→    const fieldPath = ctx.callbackQuery.data.replace('s:toggle:', '');
 60→    const config = core.configManager.get();
 61→    const currentValue = getConfigValue(config, fieldPath);
 62→    const newValue = !currentValue;
 63→
 64→    try {
 65→      const updates = buildNestedUpdate(fieldPath, newValue);
 66→      await core.configManager.save(updates, fieldPath);
 67→
 68→      const toast = isHotReloadable(fieldPath)
 69→        ? `✅ ${fieldPath} = ${newValue}`
 70→        : `✅ ${fieldPath} = ${newValue} (restart needed)`;
 71→      try { await ctx.answerCallbackQuery({ text: toast }); } catch { /* expired */ }
 72→
 73→      try {
 74→        await ctx.editMessageReplyMarkup({ reply_markup: buildSettingsKeyboard(core) });
 75→      } catch { /* ignore */ }
 76→    } catch (err) {
 77→      log.error({ err, fieldPath }, 'Failed to toggle config');
 78→      try { await ctx.answerCallbackQuery({ text: '❌ Failed to update' }); } catch { /* expired */ }
 79→    }
 80→  });
 81→
 82→  bot.callbackQuery(/^s:select:/, async (ctx) => {
 83→    const fieldPath = ctx.callbackQuery.data.replace('s:select:', '');
 84→    const config = core.configManager.get();
 85→    const fieldDef = getSafeFields().find(f => f.path === fieldPath);
 86→    if (!fieldDef) return;
 87→
 88→    const options = resolveOptions(fieldDef, config) ?? [];
 89→    const currentValue = getConfigValue(config, fieldPath);
 90→    const kb = new InlineKeyboard();
 91→
 92→    for (const opt of options) {
 93→      const marker = opt === String(currentValue) ? ' ✓' : '';
 94→      kb.text(`${opt}${marker}`, `s:pick:${fieldPath}:${opt}`).row();
 95→    }
 96→    kb.text("◀️ Back", "s:back:refresh");
 97→
 98→    try { await ctx.answerCallbackQuery(); } catch { /* expired */ }
 99→
100→    try {
101→      await ctx.editMessageText(`<b>⚙️ ${fieldDef.displayName}</b>\nSelect a value:`, {
102→        parse_mode: "HTML",
103→        reply_markup: kb,
104→      });
105→    } catch { /* ignore */ }
106→  });
107→
108→  bot.callbackQuery(/^s:pick:/, async (ctx) => {
109→    const parts = ctx.callbackQuery.data.replace('s:pick:', '').split(':');
110→    const fieldPath = parts.slice(0, -1).join(':');
111→    const newValue = parts[parts.length - 1];
112→
113→    try {
114→      // For speech.stt.provider: check if the selected provider has an API key configured
115→      if (fieldPath === 'speech.stt.provider') {
116→        const config = core.configManager.get();
117→        const providerConfig = config.speech?.stt?.providers?.[newValue];
118→        if (!providerConfig?.apiKey) {
119→          // No API key — delegate to assistant to collect it
120→          const assistant = getAssistantSession();
121→          if (assistant) {
122→            try { await ctx.answerCallbackQuery({ text: `🔑 API key needed — check Assistant topic` }); } catch { /* expired */ }
123→            const prompt = `User wants to enable ${newValue} as Speech-to-Text provider, but no API key is configured yet. Guide them to get a ${newValue} API key and set it up. After they provide the key, run both commands: \`openacp config set speech.stt.providers.${newValue}.apiKey <key>\` and \`openacp config set speech.stt.provider ${newValue}\``;
124→            await assistant.enqueuePrompt(prompt);
125→            return;
