import type { Bot, Context } from "grammy";
import { InlineKeyboard } from "grammy";
import type { OpenACPCore } from "../../../core/index.js";
import { getSafeFields, resolveOptions, getConfigValue, isHotReloadable, type ConfigFieldDef } from "../../../core/config-registry.js";
import { createChildLogger } from "../../../core/log.js";

const log = createChildLogger({ module: "telegram-settings" });

function buildSettingsKeyboard(core: OpenACPCore): InlineKeyboard {
  const config = core.configManager.get();
  const fields = getSafeFields();
  const kb = new InlineKeyboard();

  for (const field of fields) {
    const value = getConfigValue(config, field.path);
    const label = formatFieldLabel(field, value);

    if (field.type === 'toggle') {
      kb.text(`${label}`, `s:toggle:${field.path}`).row();
    } else if (field.type === 'select') {
      kb.text(`${label}`, `s:select:${field.path}`).row();
    } else {
      kb.text(`${label}`, `s:input:${field.path}`).row();
    }
  }

  kb.text("◀️ Back to Menu", "s:back");
  return kb;
}

function formatFieldLabel(field: ConfigFieldDef, value: unknown): string {
  const icons: Record<string, string> = {
    agent: '🤖', logging: '📝', tunnel: '🔗',
    security: '🔒', workspace: '📁', storage: '💾', speech: '🎤',
  };
  const icon = icons[field.group] ?? '⚙️';

  if (field.type === 'toggle') {
    return `${icon} ${field.displayName}: ${value ? 'ON' : 'OFF'}`;
  }
  const displayValue = value === null || value === undefined ? 'Not set' : String(value);
  return `${icon} ${field.displayName}: ${displayValue}`;
}

export async function handleSettings(ctx: Context, core: OpenACPCore): Promise<void> {
  const kb = buildSettingsKeyboard(core);
  await ctx.reply(`<b>⚙️ Settings</b>\nTap to change:`, {
    parse_mode: "HTML",
    reply_markup: kb,
  });
}

export function setupSettingsCallbacks(
  bot: Bot,
  core: OpenACPCore,
  getAssistantSession: () => { topicId: number; enqueuePrompt: (p: string) => Promise<void> } | undefined,
): void {
  bot.callbackQuery(/^s:toggle:/, async (ctx) => {
    const fieldPath = ctx.callbackQuery.data.replace('s:toggle:', '');
    const config = core.configManager.get();
    const currentValue = getConfigValue(config, fieldPath);
    const newValue = !currentValue;

    try {
      const updates = buildNestedUpdate(fieldPath, newValue);
      await core.configManager.save(updates, fieldPath);

      const toast = isHotReloadable(fieldPath)
        ? `✅ ${fieldPath} = ${newValue}`
        : `✅ ${fieldPath} = ${newValue} (restart needed)`;
      try { await ctx.answerCallbackQuery({ text: toast }); } catch { /* expired */ }

      try {
        await ctx.editMessageReplyMarkup({ reply_markup: buildSettingsKeyboard(core) });
      } catch { /* ignore */ }
    } catch (err) {
      log.error({ err, fieldPath }, 'Failed to toggle config');
      try { await ctx.answerCallbackQuery({ text: '❌ Failed to update' }); } catch { /* expired */ }
    }
  });

  bot.callbackQuery(/^s:select:/, async (ctx) => {
    const fieldPath = ctx.callbackQuery.data.replace('s:select:', '');
    const config = core.configManager.get();
    const fieldDef = getSafeFields().find(f => f.path === fieldPath);
    if (!fieldDef) return;

    const options = resolveOptions(fieldDef, config) ?? [];
    const currentValue = getConfigValue(config, fieldPath);
    const kb = new InlineKeyboard();

    for (const opt of options) {
      const marker = opt === String(currentValue) ? ' ✓' : '';
      kb.text(`${opt}${marker}`, `s:pick:${fieldPath}:${opt}`).row();
    }
    kb.text("◀️ Back", "s:back:refresh");

    try { await ctx.answerCallbackQuery(); } catch { /* expired */ }

    try {
      await ctx.editMessageText(`<b>⚙️ ${fieldDef.displayName}</b>\nSelect a value:`, {
        parse_mode: "HTML",
        reply_markup: kb,
      });
    } catch { /* ignore */ }
  });

  bot.callbackQuery(/^s:pick:/, async (ctx) => {
    const parts = ctx.callbackQuery.data.replace('s:pick:', '').split(':');
    const fieldPath = parts.slice(0, -1).join(':');
    const newValue = parts[parts.length - 1];

    try {
      // For speech.stt.provider: check if the selected provider has an API key configured
      if (fieldPath === 'speech.stt.provider') {
        const config = core.configManager.get();
        const providerConfig = config.speech?.stt?.providers?.[newValue];
        if (!providerConfig?.apiKey) {
          // No API key — delegate to assistant to collect it
          const assistant = getAssistantSession();
          if (assistant) {
            try { await ctx.answerCallbackQuery({ text: `🔑 API key needed — check Assistant topic` }); } catch { /* expired */ }
            const prompt = `User wants to enable ${newValue} as Speech-to-Text provider, but no API key is configured yet. Guide them to get a ${newValue} API key and set it up. After they provide the key, run both commands: \`openacp config set speech.stt.providers.${newValue}.apiKey <key>\` and \`openacp config set speech.stt.provider ${newValue}\``;
            await assistant.enqueuePrompt(prompt);
            return;
          }
          // No assistant — just warn
          try { await ctx.answerCallbackQuery({ text: `⚠️ Set API key first: openacp config set speech.stt.providers.${newValue}.apiKey <key>` }); } catch { /* expired */ }
          return;
        }
      }

      const updates = buildNestedUpdate(fieldPath, newValue);
      await core.configManager.save(updates, fieldPath);

      try { await ctx.answerCallbackQuery({ text: `✅ ${fieldPath} = ${newValue}` }); } catch { /* expired */ }
      try {
        await ctx.editMessageText(`<b>⚙️ Settings</b>\nTap to change:`, {
          parse_mode: "HTML",
          reply_markup: buildSettingsKeyboard(core),
        });
      } catch { /* ignore */ }
    } catch (err) {
      log.error({ err, fieldPath }, 'Failed to set config');
      try { await ctx.answerCallbackQuery({ text: '❌ Failed to update' }); } catch { /* expired */ }
    }
  });

  bot.callbackQuery(/^s:input:/, async (ctx) => {
    const fieldPath = ctx.callbackQuery.data.replace('s:input:', '');
    const config = core.configManager.get();
    const fieldDef = getSafeFields().find(f => f.path === fieldPath);
    if (!fieldDef) return;

    const currentValue = getConfigValue(config, fieldPath);
    const assistant = getAssistantSession();

    if (!assistant) {
      try { await ctx.answerCallbackQuery({ text: '⚠️ Start the assistant first (/assistant)' }); } catch { /* expired */ }
      return;
    }

    try { await ctx.answerCallbackQuery({ text: `Delegating to assistant...` }); } catch { /* expired */ }

    const prompt = `User wants to change ${fieldDef.displayName} (config path: ${fieldPath}). Current value: ${JSON.stringify(currentValue)}. Ask them for the new value and apply it using: openacp config set ${fieldPath} <value>`;
    await assistant.enqueuePrompt(prompt);
  });

  bot.callbackQuery("s:back", async (ctx) => {
    try { await ctx.answerCallbackQuery(); } catch { /* expired */ }
    const { buildMenuKeyboard } = await import('./menu.js');
    try {
      await ctx.editMessageText(`<b>OpenACP Menu</b>\nChoose an action:`, {
        parse_mode: "HTML",
        reply_markup: buildMenuKeyboard(),
      });
    } catch { /* ignore */ }
  });

  bot.callbackQuery("s:back:refresh", async (ctx) => {
    try { await ctx.answerCallbackQuery(); } catch { /* expired */ }
    try {
      await ctx.editMessageText(`<b>⚙️ Settings</b>\nTap to change:`, {
        parse_mode: "HTML",
        reply_markup: buildSettingsKeyboard(core),
      });
    } catch { /* ignore */ }
  });
}

function buildNestedUpdate(dotPath: string, value: unknown): Record<string, unknown> {
  const parts = dotPath.split('.');
  const result: Record<string, unknown> = {};
  let target = result;
  for (let i = 0; i < parts.length - 1; i++) {
    target[parts[i]] = {};
    target = target[parts[i]] as Record<string, unknown>;
  }
  target[parts[parts.length - 1]] = value;
  return result;
}

import type { ChatInputCommandInteraction, ButtonInteraction } from 'discord.js'
import { log } from '../../../core/log.js'
import type { DiscordAdapter } from '../adapter.js'

export async function handleSettings(
  interaction: ChatInputCommandInteraction,
  adapter: DiscordAdapter,
): Promise<void> {
  await interaction.deferReply({ ephemeral: true })

  const config = adapter.core.configManager.get()
  const configPath = adapter.core.configManager.getConfigPath()

  const installedAgents = Object.keys(adapter.core.agentCatalog.getInstalledEntries())
  const agentList = installedAgents.length > 0
    ? installedAgents.map((a: string) => a === config.defaultAgent ? `${a} (default)` : a).join(', ')
    : 'none'

  await interaction.editReply(
    `**⚙️ Settings**\n\n` +
    `**Default Agent:** ${config.defaultAgent}\n` +
    `**Installed Agents:** ${agentList}\n` +
    `**Workspace:** \`${config.workspace.baseDir}\`\n` +
    `**Max Concurrent Sessions:** ${config.security.maxConcurrentSessions}\n` +
    `**Log Level:** ${config.logging.level}\n` +
    `**Config file:** \`${configPath}\`\n\n` +
    `*To change settings, edit the config file directly or use the CLI: \`openacp config set <key> <value>\`*`,
  )
}

export async function showSettingsInfo(
  interaction: ButtonInteraction,
  adapter: DiscordAdapter,
): Promise<void> {
  const config = adapter.core.configManager.get()
  const installedAgents = Object.keys(adapter.core.agentCatalog.getInstalledEntries())
  const agentList = installedAgents.length > 0
    ? installedAgents.map((a: string) => a === config.defaultAgent ? `${a} (default)` : a).join(', ')
    : 'none'

  await interaction.followUp({
    content:
      `**⚙️ Settings**\n\n` +
      `**Default Agent:** ${config.defaultAgent}\n` +
      `**Installed Agents:** ${agentList}\n` +
      `**Workspace:** \`${config.workspace.baseDir}\`\n` +
      `**Max Concurrent Sessions:** ${config.security.maxConcurrentSessions}\n\n` +
      `*Use \`/settings\` or \`openacp config\` to view full configuration.*`,
    ephemeral: true,
  })
}

export async function handleSettingsButton(
  interaction: ButtonInteraction,
  adapter: DiscordAdapter,
): Promise<void> {
  // Stub: settings button callbacks not yet implemented for Discord
  log.debug({ customId: interaction.customId }, '[discord-settings] Button stub called')
  try {
    await showSettingsInfo(interaction, adapter)
  } catch (err) {
    log.warn({ err }, '[discord-settings] Settings button handler failed')
    try {
      await interaction.reply({
        content: '⚙️ Use `/settings` to view configuration.',
        ephemeral: true,
      })
    } catch { /* ignore */ }
  }
}

import * as fs from "node:fs";
import * as path from "node:path";
import * as os from "node:os";
import type { Config } from './config.js'

export interface ConfigFieldDef {
  path: string
  displayName: string
  group: string
  type: 'toggle' | 'select' | 'number' | 'string'
  options?: string[] | ((config: Config) => string[])
  scope: 'safe' | 'sensitive'
  hotReload: boolean
}

export const CONFIG_REGISTRY: ConfigFieldDef[] = [
  {
    path: 'defaultAgent',
    displayName: 'Default Agent',
    group: 'agent',
    type: 'select',
    options: (config) => {
      try {
        const agentsPath = path.join(os.homedir(), ".openacp", "agents.json");
        if (fs.existsSync(agentsPath)) {
          const data = JSON.parse(fs.readFileSync(agentsPath, "utf-8"));
          return Object.keys(data.installed ?? {});
        }
      } catch { /* fallback */ }
      return Object.keys(config.agents ?? {});
    },
    scope: 'safe',
    hotReload: true,
  },
  {
    path: 'logging.level',
    displayName: 'Log Level',
    group: 'logging',
    type: 'select',
    options: ['silent', 'debug', 'info', 'warn', 'error', 'fatal'],
    scope: 'safe',
    hotReload: true,
  },
  {
    path: 'tunnel.enabled',
    displayName: 'Tunnel',
    group: 'tunnel',
    type: 'toggle',
    scope: 'safe',
    hotReload: false,
  },
  {
    path: 'security.maxConcurrentSessions',
    displayName: 'Max Concurrent Sessions',
    group: 'security',
    type: 'number',
    scope: 'safe',
    hotReload: true,
  },
  {
    path: 'security.sessionTimeoutMinutes',
    displayName: 'Session Timeout (min)',
    group: 'security',
    type: 'number',
    scope: 'safe',
    hotReload: true,
  },
  {
    path: 'workspace.baseDir',
    displayName: 'Workspace Directory',
    group: 'workspace',
    type: 'string',
    scope: 'safe',
    hotReload: true,
  },
  {
    path: 'sessionStore.ttlDays',
    displayName: 'Session Store TTL (days)',
    group: 'storage',
    type: 'number',
    scope: 'safe',
    hotReload: true,
  },
  {
    path: 'speech.stt.provider',
    displayName: 'Speech to Text',
    group: 'speech',
    type: 'select',
    options: ['groq'],
    scope: 'safe',
    hotReload: true,
  },
  {
    path: 'speech.stt.apiKey',
    displayName: 'STT API Key',
    group: 'speech',
    type: 'string',
    scope: 'sensitive',
    hotReload: true,
  },
  {
    path: 'speech.tts.provider',
    displayName: 'Text to Speech',
    group: 'speech',
    type: 'select',
    options: ['edge-tts'],
    scope: 'safe',
    hotReload: true,
  },
  {
    path: 'speech.tts.providers.edge-tts.voice',
    displayName: 'Edge TTS Voice',
    group: 'speech',
    type: 'select',
    options: [
      'en-US-AriaNeural', 'en-US-GuyNeural', 'en-US-JennyNeural',
      'en-GB-SoniaNeural', 'en-AU-NatashaNeural',
      'vi-VN-HoaiMyNeural', 'vi-VN-NamMinhNeural',
      'zh-CN-XiaoxiaoNeural', 'zh-CN-YunxiNeural',
      'ja-JP-NanamiNeural', 'ja-JP-KeitaNeural',
      'ko-KR-SunHiNeural', 'ko-KR-InJoonNeural',
      'es-ES-ElviraNeural', 'fr-FR-DeniseNeural',
      'de-DE-KatjaNeural', 'pt-BR-FranciscaNeural',
      'hi-IN-SwaraNeural', 'ar-SA-ZariyahNeural',
    ],
    scope: 'safe',
    hotReload: true,
  },
]

export function getFieldDef(path: string): ConfigFieldDef | undefined {
  return CONFIG_REGISTRY.find((f) => f.path === path)
}

export function getSafeFields(): ConfigFieldDef[] {
  return CONFIG_REGISTRY.filter((f) => f.scope === 'safe')
}

export function isHotReloadable(path: string): boolean {
  const def = getFieldDef(path)
  return def?.hotReload ?? false
}

export function resolveOptions(def: ConfigFieldDef, config: Config): string[] | undefined {
  if (!def.options) return undefined
  return typeof def.options === 'function' ? def.options(config) : def.options
}

export function getConfigValue(config: Config, path: string): unknown {
  const parts = path.split('.')
  let current: unknown = config
  for (const part of parts) {
    if (current && typeof current === 'object' && part in current) {
      current = (current as Record<string, unknown>)[part]
    } else {
      return undefined
    }
  }
  return current
}

import type { OpenACPCore } from '../../core/core.js'
import type { Session } from '../../core/session.js'
import { log } from '../../core/log.js'
import { PRODUCT_GUIDE } from '../../product-guide.js'

export interface SpawnAssistantResult {
  session: Session
  /** Resolves when the background system prompt completes (or fails). */
  ready: Promise<void>
}

/**
 * Spawns an assistant session for the Discord adapter.
 * Creates a session with the default agent, sets the threadId to the given Discord thread/channel,
 * and fires a system prompt in the background.
 */
export async function spawnAssistant(
  core: OpenACPCore,
  threadId: string,
): Promise<SpawnAssistantResult> {
  const config = core.configManager.get()

  log.info({ agent: config.defaultAgent, threadId }, '[discord-assistant] Creating assistant session...')

  const session = await core.createSession({
    channelId: 'discord',
    agentName: config.defaultAgent,
    workingDirectory: core.configManager.resolveWorkspace(),
    initialName: 'Assistant', // Prevent auto-naming from triggering after system prompt
  })
  session.threadId = threadId

  log.info({ sessionId: session.id, threadId }, '[discord-assistant] Assistant agent spawned')

  // Build dynamic context for system prompt
  const systemPrompt = buildAssistantSystemPrompt(core)

  // Fire system prompt in background — don't block startup
  const ready = session
    .enqueuePrompt(systemPrompt)
    .then(() => {
      log.info({ sessionId: session.id }, '[discord-assistant] System prompt completed')
    })
    .catch((err) => {
      log.warn({ err }, '[discord-assistant] System prompt failed')
    })

  return { session, ready }
}

/**
 * Build a welcome message summarising active sessions and available agents.
 */
export function buildWelcomeMessage(core: OpenACPCore): string {
  const allRecords = core.sessionManager.listRecords()
  const activeCount = allRecords.filter(
    (r) => r.status === 'active' || r.status === 'initializing',
  ).length
  const errorCount = allRecords.filter((r) => r.status === 'error').length
  const totalCount = allRecords.length

  const installedEntries = core.agentCatalog.getInstalledEntries()
  const agents = Object.keys(installedEntries)
  const config = core.configManager.get()
  const defaultAgent = config.defaultAgent

  const agentList = agents
    .map((a) => `${a}${a === defaultAgent ? ' (default)' : ''}`)
    .join(', ')

  if (totalCount === 0) {
    return `👋 **OpenACP is ready!**\n\nNo sessions yet. Use \`/new\` to start, or ask me anything!\n\nAgents: ${agentList}`
  }

  if (errorCount > 0) {
    return (
      `👋 **OpenACP is ready!**\n\n` +
      `📊 ${activeCount} active, ${errorCount} errors / ${totalCount} total\n` +
      `⚠️ ${errorCount} session${errorCount > 1 ? 's have' : ' has'} errors — ask me to check.\n\n` +
      `Agents: ${agentList}`
    )
  }

  return (
    `👋 **OpenACP is ready!**\n\n` +
    `📊 ${activeCount} active / ${totalCount} total\n` +
    `Agents: ${agentList}`
  )
}

/**
 * Build the system prompt for the Discord assistant session.
 * Includes current state, available agents, and action playbook.
 */
export function buildAssistantSystemPrompt(core: OpenACPCore): string {
  const config = core.configManager.get()

  const allRecords = core.sessionManager.listRecords()
  const activeCount = allRecords.filter(
    (r) => r.status === 'active' || r.status === 'initializing',
  ).length

  const statusCounts = new Map<string, number>()
  for (const r of allRecords) {
    statusCounts.set(r.status, (statusCounts.get(r.status) ?? 0) + 1)
  }
  const topicBreakdown =
    Array.from(statusCounts.entries())
      .map(([status, count]) => `${status}: ${count}`)
      .join(', ') || 'none'

  const installedEntries = core.agentCatalog.getInstalledEntries()
  const installedAgents = Object.keys(installedEntries)
  const agentNames = installedAgents.length ? installedAgents.join(', ') : Object.keys(config.agents).join(', ')

  const availableItems = core.agentCatalog.getAvailable()
  const availableAgentCount = availableItems.filter((i) => !i.installed).length

  return `You are the OpenACP Assistant — a helpful guide for managing AI coding sessions on Discord.

## Current State
- Active sessions: ${activeCount} / ${allRecords.length} total
- Sessions by status: ${topicBreakdown}
- Installed agents: ${agentNames}
- Available in ACP Registry: ${availableAgentCount} more agents (use \`/agents\` to browse)
- Default agent: ${config.defaultAgent}
- Workspace base directory: ${config.workspace.baseDir}
- Platform: Discord

## Discord Context
- Each session gets its own forum thread in the OpenACP sessions channel
- Users interact with sessions by chatting in those threads
- Slash commands: /new, /cancel, /status, /sessions, /agents, /install, /menu, /help, /dangerous, /restart, /update, /integrate, /settings, /doctor, /handoff, /clear

## Action Playbook

### Create Session
- The workspace is the project directory where the agent will work (read, write, execute code). It should be a specific project folder like \`~/code/my-project\` or \`${config.workspace.baseDir}/my-app\`.
- Ask which agent to use (if multiple are installed). Installed: ${agentNames}
- Ask which project directory to use as workspace. Suggest \`${config.workspace.baseDir}\` as the base.
- Create via: \`openacp api new <agent> <workspace>\`

### Browse & Install Agents
- Guide users to \`/agents\` command to see all available agents
- For CLI users: \`openacp agents install <name>\`
- Some agents need login/setup after install — guide users to \`openacp agents info <name>\`
- To run agent CLI for login: \`openacp agents run <name> -- <args>\`

### Check Status / List Sessions
- Run \`openacp api status\` for active sessions overview
- Run \`openacp api topics\` for full list with statuses

### Cancel Session
- Run \`openacp api status\` to see what's active
- If 1 active session → ask user to confirm → \`openacp api cancel <id>\`
- If multiple → list them, ask user which one to cancel

### Troubleshoot
- Run \`openacp api health\` + \`openacp api status\` to diagnose
- Small issue (stuck session) → suggest cancel + create new
- Big issue (system-level) → suggest restart, ask for confirmation first

### Cleanup Old Sessions
- Run \`openacp api topics --status finished,error\` to see what can be cleaned
- Report the count, ask user to confirm
- Execute: \`openacp api cleanup --status <statuses>\`

### Configuration
- View: \`openacp config\`
- Update: \`openacp config set <key> <value>\`

### Restart / Update
- Always ask for confirmation — these are disruptive actions

### Toggle Dangerous Mode
- Run \`openacp api dangerous <id> on|off\`
- Explain: dangerous mode auto-approves all permission requests

## CLI Commands Reference
\`\`\`bash
# Session management
openacp api status                       # List active sessions
openacp api session <id>                 # Session detail
openacp api new <agent> <workspace>      # Create new session
openacp api send <id> "prompt text"      # Send prompt to session
openacp api cancel <id>                  # Cancel session
openacp api dangerous <id> on|off        # Toggle dangerous mode

# Topic management
openacp api topics                       # List all topics
openacp api cleanup                      # Cleanup finished topics

# Agent management
openacp agents                           # List installed + available agents
openacp agents install <name>            # Install agent from ACP Registry
openacp agents uninstall <name>          # Remove agent
openacp agents info <name>               # Show details & setup guide
openacp agents run <name> -- <args>      # Run agent CLI (for login, etc.)

# System
openacp api health                       # System health
openacp config                           # Edit config (interactive)
openacp config set <key> <value>         # Update config value
openacp api restart                      # Restart daemon
\`\`\`

## Guidelines
- NEVER show \`openacp api ...\` commands to users. These are internal tools for YOU to run silently.
- Run \`openacp api ...\` commands yourself for everything you can. Only guide users to Discord slash commands/buttons when needed.
- When creating sessions: guide user through agent + workspace choice conversationally, then run the command yourself.
- Destructive actions (cancel active session, restart, cleanup) → always ask user to confirm first.
- Respond in the same language the user uses.
- Format responses for Discord: use **bold**, \`code\`, keep it concise.
- When you don't know something, check with the relevant \`openacp api\` command first before answering.

## Product Reference
${PRODUCT_GUIDE}`
}

